struct font_char_info
{
  int x0;
  int y0;
  int x1;
  int y1;
  int adv;
  int bitmap;
};

class font_def
{
public:
  const font_char_info* get_char_info(char c) const;
  void render(const stringx& s, color32 clr, float& x, float y, float z,
              float rhw, float scale=1.0f) const;
};

template <class T>
class list
{
  struct node
  {
    node *next;
    node *prev;
    T data;
  };

public:
  class iterator
  {
  public:
    node *current;
    iterator() {}
    iterator(node *n) : current(n) {}
    T& operator*() const { return current->data; }
    iterator& operator++()
    {
      current = current->next;
      return *this;
    }
    bool operator!=(const iterator& other) const
    {
      return current != other.current;
    }
  };

  node *sentinel;
  iterator begin() { return iterator(sentinel->next); }
  iterator end() { return iterator(sentinel); }
};

class element;
typedef list<element *> element_list_t;

